"use client";

import Image from "next/image";
import { useTheme } from "next-themes";

/** AURA logo mark — dark/light via CSS, no hydration flash */
export function AuraLogo({ size = 16 }: { size?: number }) {
  return (
    <>
      <Image
        src="/dark-logo.svg"
        alt="AURA"
        width={size}
        height={size}
        className="hidden dark:block"
      />
      <Image
        src="/light-logo.svg"
        alt="AURA"
        width={size}
        height={size}
        className="block dark:hidden"
      />
    </>
  );
}

